#include "logos_graph.h"
#include <algorithm>
namespace logos {
struct ClaimValue{std::string id,subject,predicate,scope,time;u64 kind{};std::string text;u64 number{};};static bool single(std::string_view p){return p=="write_count"||p=="receiver_content_sha256"||p=="duplicate_second_effect";}static Status claim_value(const GraphState&g,const ObjectStore&s,const NodeEntry&n,ClaimValue*out){Buffer b;LgoObjectView v{};auto st=graph_load_node(g,s,n.semantic_id,&b,&v);if(st!=Status::Ok)return st;out->id=n.semantic_id;if(lgo_get_utf8(v,F_SUBJECT_ID,&out->subject)!=Status::Ok||lgo_get_utf8(v,F_PREDICATE,&out->predicate)!=Status::Ok||lgo_get_utf8(v,F_SCOPE,&out->scope)!=Status::Ok||lgo_get_u64(v,F_VALUE_KIND,&out->kind)!=Status::Ok)return Status::InvariantViolation;if(lgo_get_utf8(v,F_TIME_SCOPE,&out->time)!=Status::Ok)out->time.clear();if(out->kind==(u64)ValueKind::TEXT)return lgo_get_utf8(v,F_VALUE_TEXT,&out->text);return lgo_get_u64(v,F_VALUE_U64,&out->number);}static bool unequal(const ClaimValue&a,const ClaimValue&b){return a.kind==(u64)ValueKind::TEXT?a.text!=b.text:a.number!=b.number;}static std::string contradiction_id(std::string a,std::string b){if(b<a)std::swap(a,b);std::string m=a;m.push_back('\0');m+=b;auto d=sha256({(const u8*)m.data(),(u64)m.size()});return"CTR-"+hex(d).substr(0,16);}Status detect_contradictions(GraphState*g,ObjectStore*s,Ledger*l){std::vector<ClaimValue>c;for(auto&kv:g->nodes){auto&n=kv.second;if(n.type==NodeType::CLAIM){ClaimValue x{};auto st=claim_value(*g,*s,n,&x);if(st!=Status::Ok)return st;if(single(x.predicate))c.push_back(x);}}for(size_t i=0;i<c.size();i++)for(size_t j=i+1;j<c.size();j++){auto&a=c[i],&b=c[j];if(a.subject!=b.subject||a.predicate!=b.predicate||a.scope!=b.scope||a.time!=b.time||a.kind!=b.kind||!unequal(a,b))continue;std::string id=contradiction_id(a.id,b.id);if(g->nodes.count(id))continue;std::string lo=a.id,hi=b.id;if(hi<lo)std::swap(lo,hi);LgoBuilder q{};Buffer z;lgo_begin(&q);lgo_add_u64(&q,F_RECORD_KIND,1);lgo_add_u64(&q,F_NODE_TYPE,(u64)NodeType::CONTRADICTION);lgo_add_utf8(&q,F_SEMANTIC_ID,id);lgo_add_u64(&q,F_REVISION,1);lgo_add_u64(&q,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_utf8(&q,F_STATUS,"OPEN");lgo_add_utf8(&q,F_MEMBER_A_ID,lo);lgo_add_utf8(&q,F_MEMBER_B_ID,hi);lgo_finish(&q,&z,nullptr);auto st=graph_add_node(s,l,g,{z.data(),(u64)z.size()},nullptr);if(st!=Status::Ok&&st!=Status::NodeExists)return st;}return Status::Ok;}
}
